solutionCodeJson.code:
// main.js — let tạo biến mới cho MỖI vòng lặp ⇒ mỗi closure nhớ đúng giá trị của nó
function makeCounters(n) {
  const fns = []; // const: không gán lại biến fns (vẫn push được — const ≠ bất biến)
  for (let i = 0; i < n; i++) {
    fns.push(() => i);
  }
  return fns;
}

