// main.js — arrow function lấy this của start() ⇒ this.seconds đúng là của timer
function createTimer(limit) {
  return {
    seconds: 0,
    id: null,
    start() {
      if (this.id !== null) return; // đang chạy ⇒ không tạo thêm interval
      this.id = setInterval(() => {
        this.seconds += 1;
        if (this.seconds >= limit) this.stop();
      }, 1000);
    },
    stop() {
      clearInterval(this.id);
      this.id = null;
    },
  };
}

