// main.js — closure: biến của hàm ngoài sống tiếp trong hàm được trả về
function once(fn) {
  let done = false; // dùng CỜ, không dựa vào giá trị result (fn có thể trả 0/undefined)
  let result;
  return (...args) => {
    if (!done) {
      done = true;
      result = fn(...args);
    }
    return result;
  };
}

function memoize(fn) {
  const cache = new Map(); // tạo MỘT lần cho mỗi hàm được memoize
  return (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const value = fn(...args);
    cache.set(key, value);
    return value;
  };
}
